const WORLD_UP = new THREE.Vector3(0, 1, 0);

function toParentSpace(object3D, worldPoint) {
  if (!object3D?.parent) {
    return worldPoint;
  }
  return object3D.parent.worldToLocal(worldPoint.clone());
}

function resolveTargetAnchor(target) {
  return target?.anchors?.pourTarget || target?.anchors?.mouth || null;
}

function resolveInteractionId(kind, source, target) {
  const sourceId = getApparatusId(source);
  const targetId = target ? getApparatusId(target) : kind;
  return `${kind}:${sourceId}->${targetId}`;
}

function createPourInteraction({
  source,
  target,
  streamMesh,
  options = {},
}) {
  const sourceAnchor = source?.anchors?.nozzle;
  const targetAnchor = resolveTargetAnchor(target);
  const visibilityMargin = options.visibilityMargin ?? 0.04;
  const streamVisibleFrom = options.streamVisibleFrom ?? 0.08;
  const streamVisibleUntil = options.streamVisibleUntil ?? 0.96;
  const streamRadiusScale = options.streamRadiusScale ?? [1, 1];
  const sourceFillRange = options.sourceFillRange ?? null;
  const streamOpacityRange = options.streamOpacityRange ?? [0.22, 0.68];
  const id = resolveInteractionId('pour', source, target);

  const state = {
    progress: 0,
  };

  function updateStream(progress, runtime = {}) {
    if (!streamMesh || !sourceAnchor || !targetAnchor) {
      return;
    }

    const visible = typeof options.getStreamVisible === 'function'
      ? !!options.getStreamVisible(progress, runtime)
      : progress > streamVisibleFrom && progress < streamVisibleUntil;
    streamMesh.visible = visible;
    if (!visible) {
      return;
    }

    const origin = toParentSpace(streamMesh, getAnchorWorld(sourceAnchor));
    const targetPoint = toParentSpace(streamMesh, getAnchorWorld(targetAnchor));
    const direction = targetPoint.clone().sub(origin);
    const length = Math.max(direction.length(), 0.1);
    const mid = origin.clone().lerp(targetPoint, 0.5);
    streamMesh.position.copy(mid);
    streamMesh.scale.set(streamRadiusScale[0], length, streamRadiusScale[1]);
    streamMesh.quaternion.setFromUnitVectors(WORLD_UP, direction.clone().normalize());
    if (streamMesh.material) {
      streamMesh.material.opacity = THREE.MathUtils.lerp(
        streamOpacityRange[0],
        streamOpacityRange[1],
        progress
      );
    }
  }

  function updateSource(progress, runtime = {}) {
    if (source?.controllers?.setPourPose) {
      source.controllers.setPourPose(progress);
    }
    if ((sourceFillRange || typeof options.getSourceFill === 'function') && source?.controllers?.setLiquidLevel) {
      const nextFill = typeof options.getSourceFill === 'function'
        ? options.getSourceFill(progress, runtime)
        : THREE.MathUtils.lerp(sourceFillRange[0], sourceFillRange[1], progress);
      source.controllers.setLiquidLevel(nextFill);
    }
  }

  return {
    id,
    kind: 'pour',
    source,
    target,
    state,
    setProgress(progress, runtime = {}) {
      const value = clamp(progress, 0, 1);
      state.progress = value;
      updateSource(value, runtime);
      updateStream(value, runtime);
    },
    reset() {
      state.progress = 0;
      updateSource(0);
      if (streamMesh) {
        streamMesh.visible = false;
      }
    },
    validate(camera) {
      const reports = [validatePourAlignment(source, target)];
      if (camera && sourceAnchor && targetAnchor) {
        reports.push(
          validateVisibility(camera, this.getVisibilityPoints(), { margin: visibilityMargin })
        );
      }
      return reports.map((report) => ({
        ...report,
        interactionId: id,
      }));
    },
    getVisibilityPoints() {
      if (!sourceAnchor || !targetAnchor) {
        return [];
      }
      return [
        {
          label: `${id}:source`,
          interactionId: id,
          apparatusId: getApparatusId(source),
          point: getAnchorWorld(sourceAnchor),
        },
        {
          label: `${id}:target`,
          interactionId: id,
          apparatusId: getApparatusId(target),
          point: getAnchorWorld(targetAnchor),
        },
      ];
    },
  };
}

function createDripInteraction({
  source,
  target,
  dropMesh,
  options = {},
}) {
  const sourceAnchor = source?.anchors?.nozzle;
  const targetAnchor = target?.anchors?.mouth || resolveTargetAnchor(target);
  const id = resolveInteractionId('drip', source, target);
  const visibleFrom = options.visibleFrom ?? 0.1;
  const visibleUntil = options.visibleUntil ?? 0.38;
  const fallWindow = options.fallWindow ?? [0.08, 0.22];

  const state = {
    progress: 0,
  };

  return {
    id,
    kind: 'drip',
    source,
    target,
    state,
    setProgress(progress) {
      const value = clamp(progress, 0, 1);
      state.progress = value;
      if (!dropMesh || !sourceAnchor || !targetAnchor) {
        return;
      }
      const visible = value > visibleFrom && value < visibleUntil;
      dropMesh.visible = visible;
      if (!visible) {
        return;
      }
      const origin = toParentSpace(dropMesh, getAnchorWorld(sourceAnchor));
      const targetPoint = toParentSpace(dropMesh, getAnchorWorld(targetAnchor));
      const fall = THREE.MathUtils.smoothstep(value, fallWindow[0], fallWindow[1]);
      dropMesh.position.copy(origin.lerp(targetPoint, fall));
    },
    reset() {
      state.progress = 0;
      if (dropMesh) {
        dropMesh.visible = false;
      }
    },
    validate() {
      return [];
    },
    getVisibilityPoints() {
      if (!dropMesh || !dropMesh.visible) {
        return [];
      }
      return [{
        label: `${id}:drop`,
        interactionId: id,
        point: dropMesh.position.clone(),
      }];
    },
  };
}

function createHeatInteraction({
  vessel,
  burner,
  effect = {},
  options = {},
}) {
  const burnerAnchor = burner?.anchors?.flameOrigin || burner?.anchors?.heatZone;
  const vesselAnchor = vessel?.anchors?.heatZone || vessel?.anchors?.steamOrigin || vessel?.anchors?.effectOrigin;
  const id = resolveInteractionId('heat', burner, vessel);
  const flameMesh = effect.flameMesh || null;
  const glowMesh = effect.glowMesh || null;
  const maxOpacity = options.maxOpacity ?? 0.86;

  const state = {
    intensity: 0,
  };

  function setVisual(mesh, intensity, scaleBoost) {
    if (!mesh) {
      return;
    }
    mesh.visible = intensity > 0.02;
    if (!mesh.visible) {
      return;
    }
    mesh.scale.setScalar(1 + intensity * scaleBoost);
    if (mesh.material) {
      mesh.material.opacity = Math.min(maxOpacity, intensity * maxOpacity);
    }
  }

  return {
    id,
    kind: 'heat',
    state,
    setIntensity(value) {
      const intensity = clamp(value, 0, 1);
      state.intensity = intensity;
      if (burnerAnchor && flameMesh) {
        flameMesh.position.copy(toParentSpace(flameMesh, getAnchorWorld(burnerAnchor)));
      }
      if (vesselAnchor && glowMesh) {
        glowMesh.position.copy(toParentSpace(glowMesh, getAnchorWorld(vesselAnchor)));
      }
      setVisual(flameMesh, intensity, 0.2);
      setVisual(glowMesh, intensity, 0.12);
    },
    reset() {
      this.setIntensity(0);
    },
    validate(camera) {
      const reports = [];
      if (camera) {
        reports.push(
          validateVisibility(camera, this.getVisibilityPoints(), {
            margin: options.visibilityMargin ?? 0.04,
          })
        );
      }
      return reports.map((report) => ({
        ...report,
        interactionId: id,
      }));
    },
    getVisibilityPoints() {
      const points = [];
      if (burnerAnchor) {
        points.push({
          label: `${id}:burner`,
          interactionId: id,
          apparatusId: getApparatusId(burner),
          point: getAnchorWorld(burnerAnchor),
        });
      }
      if (vesselAnchor) {
        points.push({
          label: `${id}:vessel`,
          interactionId: id,
          apparatusId: getApparatusId(vessel),
          point: getAnchorWorld(vesselAnchor),
        });
      }
      return points;
    },
  };
}

function createSteamInteraction({
  vessel,
  effect = {},
  options = {},
}) {
  const steamAnchor = vessel?.anchors?.steamOrigin || vessel?.anchors?.effectOrigin;
  const effectMesh = effect.mesh || null;
  const id = resolveInteractionId('steam', vessel);
  const maxOpacity = options.maxOpacity ?? 0.24;

  const state = {
    intensity: 0,
  };

  return {
    id,
    kind: 'steam',
    state,
    setIntensity(value) {
      const intensity = clamp(value, 0, 1);
      state.intensity = intensity;
      if (!effectMesh || !steamAnchor) {
        return;
      }
      effectMesh.visible = intensity > 0.02;
      effectMesh.position.copy(toParentSpace(effectMesh, getAnchorWorld(steamAnchor)));
      effectMesh.scale.setScalar(1 + intensity * 0.22);
      if (effectMesh.material) {
        effectMesh.material.opacity = Math.min(maxOpacity, intensity * maxOpacity);
      }
    },
    reset() {
      this.setIntensity(0);
    },
    validate(camera) {
      const reports = [];
      if (camera) {
        reports.push(
          validateVisibility(camera, this.getVisibilityPoints(), {
            margin: options.visibilityMargin ?? 0.04,
          })
        );
      }
      return reports.map((report) => ({
        ...report,
        interactionId: id,
      }));
    },
    getVisibilityPoints() {
      if (!steamAnchor) {
        return [];
      }
      return [{
        label: `${id}:steam`,
        interactionId: id,
        apparatusId: getApparatusId(vessel),
        point: getAnchorWorld(steamAnchor),
      }];
    },
  };
}

const WORLD_POINT = new THREE.Vector3();

const FALLBACK_SOURCE = { kind: 'source', meta: { id: 'source' } };
const FALLBACK_TARGET = { kind: 'target', meta: { id: 'target' } };

function getWorldPoint(object3D) {
  return object3D.getWorldPosition(WORLD_POINT.clone());
}

function makeInteractionRef(entry, fallbackKind, fallbackId) {
  return entry ?? { kind: fallbackKind, meta: { id: fallbackId } };
}

function resolveTargetAnchorObject(target, anchorName) {
  return resolveAnchor(target, anchorName)
    ?? target?.anchors?.interactionZone
    ?? target?.anchors?.pourTarget
    ?? target?.anchors?.sampleZone
    ?? target?.anchors?.mouth
    ?? null;
}

function getCurrentCompleted(options) {
  return typeof options.getCompleted === 'function' ? options.getCompleted() : {};
}

function getCurrentCompletion(source, getCompletionPose, duration) {
  return resolveCompletionEntry({
    source,
    getCompletionPose,
    duration,
  });
}

function canStartStep(stepKey, order, options) {
  return canAttemptOrderedStep(stepKey, order, getCurrentCompleted(options));
}

function buildCompletionHandler(stepKey, state, order, options, getCompletion) {
  return completeOrderedOverlapStep({
    key: stepKey,
    state,
    order,
    completed: getCurrentCompleted(options),
    isReady: (currentKey) => currentKey === stepKey && (typeof options.isReady !== 'function' || options.isReady(currentKey)),
    getCompletion,
  });
}

function updateCompletion(state, getCompletion, options, dt) {
  return runStepCompletion(state, dt, getCompletion, (completedKey, current) => {
    options.onComplete?.(completedKey, current);
  });
}

function getVisibilityPoints(id, sourceGroup, targetGroup, sourceId, targetId, targetAnchorObject) {
  const points = [];
  if (sourceGroup) {
    points.push({
      label: `${id}:source`,
      interactionId: id,
      apparatusId: sourceId,
      point: getWorldPoint(sourceGroup),
    });
  }
  if (targetAnchorObject) {
    points.push({
      label: `${id}:target`,
      interactionId: id,
      apparatusId: targetId,
      point: getWorldPoint(targetAnchorObject),
    });
  } else if (targetGroup) {
    points.push({
      label: `${id}:target`,
      interactionId: id,
      apparatusId: targetId,
      point: getWorldPoint(targetGroup),
    });
  }
  return points;
}

function createInteractionId(source, target, sourceId, targetId) {
  return resolveInteractionId(
    'overlap-completion',
    makeInteractionRef(source, FALLBACK_SOURCE.kind, sourceId || FALLBACK_SOURCE.meta.id),
    makeInteractionRef(target, FALLBACK_TARGET.kind, targetId || FALLBACK_TARGET.meta.id),
  );
}

function resolveStepKey(key, sourceId) {
  return key ?? sourceId;
}

function resolvePadding(options) {
  return options.padding ?? 0.12;
}

function resolveDuration(options) {
  return options.duration ?? 0.25;
}

function resolveOrder(options) {
  return Array.isArray(options.order) ? options.order : [];
}

function resolveState(options) {
  return options.state ?? {};
}

function canOverlap(sourceGroup, targetGroup, padding) {
  if (!sourceGroup || !targetGroup) {
    return false;
  }
  return modelsOverlapOrNear(sourceGroup, targetGroup, padding);
}

function resetCompletion(state) {
  clearStepCompletion(state);
}

function hasCompletion(state, stepKey) {
  return hasActiveCompletion(state, stepKey);
}

function isInteractionBusy(state, stepKey) {
  return isStepBusy(state, stepKey);
}

function getTargetId(key, target) {
  return target ? getApparatusId(target) : key || FALLBACK_TARGET.meta.id;
}

function getSourceId(source) {
  return getApparatusId(source);
}

function resolveSourceGroup(source) {
  return resolveGroup(source);
}

function resolveTargetGroup(target) {
  return resolveGroup(target);
}

function createCompletionGetter(source, options, duration) {
  return () => getCurrentCompletion(source, options.getCompletionPose, duration);
}

function startCompletion(stepKey, state, order, options, getCompletion) {
  return buildCompletionHandler(stepKey, state, order, options, getCompletion);
}

function updateStepCompletion(state, getCompletion, options, dt) {
  return updateCompletion(state, getCompletion, options, dt);
}

function getInteractionVisibilityPoints(id, sourceGroup, targetGroup, sourceId, targetId, targetAnchorObject) {
  return getVisibilityPoints(id, sourceGroup, targetGroup, sourceId, targetId, targetAnchorObject);
}

function getTargetAnchor(target, targetAnchor) {
  return resolveTargetAnchorObject(target, targetAnchor);
}

function canAttempt(stepKey, order, options) {
  return canStartStep(stepKey, order, options);
}

function overlap(sourceGroup, targetGroup, padding) {
  return canOverlap(sourceGroup, targetGroup, padding);
}

function getBusyState(state, stepKey) {
  return isInteractionBusy(state, stepKey);
}

function getActiveState(state, stepKey) {
  return hasCompletion(state, stepKey);
}

function doReset(state) {
  return resetCompletion(state);
}

function buildId(source, target, sourceId, targetId) {
  return createInteractionId(source, target, sourceId, targetId);
}

function pickStepKey(key, sourceId) {
  return resolveStepKey(key, sourceId);
}

function pickState(options) {
  return resolveState(options);
}

function pickOrder(options) {
  return resolveOrder(options);
}

function pickDuration(options) {
  return resolveDuration(options);
}

function pickPadding(options) {
  return resolvePadding(options);
}

function pickSourceId(source) {
  return getSourceId(source);
}

function pickTargetId(key, target) {
  return getTargetId(key, target);
}

function pickSourceGroup(source) {
  return resolveSourceGroup(source);
}

function pickTargetGroup(target) {
  return resolveTargetGroup(target);
}

function pickTargetAnchor(target, targetAnchor) {
  return getTargetAnchor(target, targetAnchor);
}

function pickCompletion(source, options, duration) {
  return createCompletionGetter(source, options, duration);
}

function resolveAnchor(apparatus, anchorName) {
  if (!anchorName) {
    return null;
  }
  return apparatus?.anchors?.[anchorName] ?? null;
}

function resolveGroup(entry) {
  return entry?.group || entry?.apparatus?.group || null;
}

function resolveCompletionEntry({ source, getCompletionPose, duration }) {
  const object = resolveGroup(source);
  const pose = getCompletionPose?.();
  if (!object || !pose) {
    return null;
  }
  return {
    object,
    pose,
    duration,
  };
}

function createOverlapCompletionInteraction({
  key,
  source,
  target,
  targetAnchor,
  options = {},
} = {}) {
  const sourceId = pickSourceId(source);
  const targetId = pickTargetId(key, target);
  const id = buildId(source, target, sourceId, targetId);
  const sourceGroup = pickSourceGroup(source);
  const targetGroup = pickTargetGroup(target);
  const state = pickState(options);
  const order = pickOrder(options);
  const stepKey = pickStepKey(key, sourceId);
  const duration = pickDuration(options);
  const padding = pickPadding(options);
  const targetAnchorObject = pickTargetAnchor(target, targetAnchor);
  const getCompletion = pickCompletion(source, options, duration);

  return {
    id,
    kind: 'overlap-completion',
    key: stepKey,
    source,
    target,
    state,
    canAttempt() {
      return canAttempt(stepKey, order, options);
    },
    isOverlapping() {
      return overlap(sourceGroup, targetGroup, padding);
    },
    tryStart() {
      return startCompletion(stepKey, state, order, options, getCompletion);
    },
    update(dt) {
      return updateStepCompletion(state, getCompletion, options, dt);
    },
    reset() {
      return doReset(state);
    },
    hasActiveCompletion() {
      return getActiveState(state, stepKey);
    },
    isBusy() {
      return getBusyState(state, stepKey);
    },
    getVisibilityPoints() {
      return getInteractionVisibilityPoints(id, sourceGroup, targetGroup, sourceId, targetId, targetAnchorObject);
    },
  };
}

